def combinationSum2(candidates, target):
    cs = sorted(candidates)
    res = []
    cur = []

    def go(start, remain):
        if remain == 0:
            res.append(cur[:])
            return
        for i in range(start, len(cs)):
            if cs[i] > remain:
                break
            if i > start and cs[i] == cs[i - 1]:
                continue
            cur.append(cs[i])
            go(i + 1, remain - cs[i])
            cur.pop()

    go(0, target)
    return res
